        "engagement": {
          "type": "string",
          "description": "all (everyone who reacted or commented), reactions or comments"
        },
        "maxPerPost": {
          "type": "number",
          "description": "The most people read from each post (1 to 3,000)"
        },
        "maxEngagers": {
          "type": "number",
          "description": "The most people returned for the whole search (1 to 5,000). People who commented are read first, then people who reacted."
        }
